// Renders src/film.html to an App Store-spec iPhone preview:
// 886 x 1920, 30 fps, H.264 High, ~11 Mbps, stereo 256 kbps AAC at 48 kHz,
// 25 s (Apple allows 15–30 s). The soundtrack is generated by
// scripts/score.py from the film's own event list, so sound and picture can't
// drift apart.
//
//   node scripts/render-video.mjs                # the film
//   node scripts/render-video.mjs --stills 1 9   # PNG stills at those seconds

import { execFileSync, spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { chromium, root, serve } from "./lib.mjs";

const FPS = 30;
const out = resolve(root, "export/video");
mkdirSync(out, { recursive: true });

const { server, url } = await serve();
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 443, height: 960 }, deviceScaleFactor: 2 });
page.on("pageerror", (e) => console.error(e.message));
await page.goto(`${url}/src/film.html`);
await page.waitForFunction(() => window.READY, null, { timeout: 120_000 });
const shoot = async (t, type = "jpeg") => {
  await page.evaluate((t) => window.render(t), t);
  return page.screenshot({
    type,
    quality: type === "jpeg" ? 95 : undefined,
    clip: { x: 0, y: 0, width: 443, height: 960 },
  });
};

const args = process.argv.slice(2);
if (args[0] === "--stills") {
  for (const s of args.slice(1))
    writeFileSync(resolve(out, `still-${s}s.png`), await shoot(+s, "png"));
} else {
  const duration = await page.evaluate(() => window.DURATION);
  const events = await page.evaluate(() => window.EVENTS);
  const audio = resolve(out, "score.wav");
  execFileSync(
    "python3",
    [resolve(root, "scripts/score.py"), audio, String(duration), JSON.stringify(events)],
    { stdio: "inherit" },
  );
  const file = resolve(out, "water-run-preview-886x1920.mp4");
  const ff = spawn(
    "ffmpeg",
    [
      "-y",
      "-loglevel",
      "error",
      "-f",
      "image2pipe",
      "-framerate",
      String(FPS),
      "-c:v",
      "mjpeg",
      "-i",
      "-",
      "-i",
      audio,
      "-vf",
      "scale=886:1920:flags=lanczos,format=yuv420p",
      "-c:v",
      "libx264",
      "-profile:v",
      "high",
      "-level",
      "4.0",
      "-preset",
      "slow",
      "-b:v",
      "11M",
      "-maxrate",
      "12M",
      "-bufsize",
      "16M",
      "-r",
      String(FPS),
      "-c:a",
      "aac",
      "-b:a",
      "256k",
      "-ar",
      "48000",
      "-ac",
      "2",
      "-movflags",
      "+faststart",
      "-shortest",
      file,
    ],
    { stdio: ["pipe", "inherit", "inherit"] },
  );
  const frames = Math.round(duration * FPS);
  for (let i = 0; i < frames; i++) {
    const buf = await shoot(i / FPS);
    if (!ff.stdin.write(buf)) await new Promise((r) => ff.stdin.once("drain", r));
    if (i % 150 === 0) console.log(`frame ${i}/${frames}`);
  }
  ff.stdin.end();
  await new Promise((r) => ff.on("close", r));
  console.log("wrote", file);
}
await browser.close();
server.close();
